def square_numbers(values):
    '''Return a new list containing each input value squared.'''
    return [value ** 2 for value in values]

def even_numbers(values):
    '''Select integers divisible by two from an iterable.'''
    return [value for value in values if value % 2 == 0]

def factorial(number):
    '''Compute factorial recursively and reject negative input.'''
    if number < 0:
        raise ValueError('number must be non-negative')
    if number in (0, 1):
        return 1
    return number * factorial(number - 1)

def word_frequency(sentence):
    '''Build a dictionary mapping lowercase words to occurrence counts.'''
    counts = {}
    for word in sentence.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def safe_divide(numerator, denominator, fallback=0):
    '''Divide numbers while handling a zero denominator.'''
    try:
        return numerator / denominator
    except ZeroDivisionError:
        return fallback

def group_by(items, key_function):
    '''Collect items under the key produced by key_function.'''
    grouped = {}
    for item in items:
        key = key_function(item)
        grouped.setdefault(key, []).append(item)
    return grouped

class RunningTotal:
    '''Maintain an accumulated numeric total.'''
    def __init__(self):
        self.total = 0

    def add(self, value):
        self.total += value
        return self.total

def first_palindrome(words):
    '''Return the first word that reads the same backwards, if any.'''
    for word in words:
        normalized = word.lower()
        if normalized == normalized[::-1]:
            return word
    return None
